    {
        DetectionViewData* state;
        BSSimpleList<TESTopicInfo*>* list;
    } detecting, detected;
    int i;
    MiddleHighProcess::Revert(buffer);
    if (m_pRevertibleObject)
        m_pRevertibleObject->ResetCacheValues();
    m_bSpellState = false;
    m_iFirstSpellIndex = -1;
    m_iSecondSpellIndex = -1;
