        m_pSavedTargetReference
            ? dynamic_cast<TESObjectREFR*>((TESForm*)TESForm::GetFormByID((unsigned int)m_pSavedTargetReference))
            : 0;
    m_pFadeReference =
        m_pFadeReference
            ? dynamic_cast<TESObjectREFR*>((TESForm*)TESForm::GetFormByID((unsigned int)m_pFadeReference))
            : 0;
